// tb/v3/tb_ch09_div.v
// Cycle-accurate, bit-exact testbench for rtl/v3/ch09_radix2_div.v
// Compatible with iverilog -g2012 -Wall
//
// Verification protocol:
// - Reads cycle vectors generated by Python twin (verify_v3/ch09_twin.py)
// - Covers 265 test triples: Hand calculation, Exercise 2, negative num,
//   small den (1, 2, 3), large den with s2 = 1..5, boundary lags tau=27 and 213,
//   and randomized triples across the full parameter space.
// - 2-phase sampling convention:
//     * Inputs driven at @(negedge clk)
//     * Registered outputs checked at @(posedge clk); #1
// - Strict loop condition, counts all errors, reports total

`timescale 1ns/1ps

module tb_ch09_div;

    localparam integer WIDTHN          = 44;
    localparam integer WIDTHD          = 34;
    localparam integer EXPECTED_CYCLES = 12456;

    // Clock generation (50 MHz, 20 ns period)
    reg clk = 0;
    always #10 clk = ~clk;

    // DUT signals
    reg              rst_n;
    reg              start;
    reg [WIDTHN-1:0] numer;
    reg [WIDTHD-1:0] denom;

    wire             busy;
    wire             done;
    wire [WIDTHN-1:0] quotient;
    wire [WIDTHD-1:0] remain;

    // Instantiate DUT
    ch09_radix2_div #(
        .WIDTHN(WIDTHN),
        .WIDTHD(WIDTHD)
    ) dut (
        .clk      (clk),
        .rst_n    (rst_n),
        .start    (start),
        .busy     (busy),
        .done     (done),
        .numer    (numer),
        .denom    (denom),
        .quotient (quotient),
        .remain   (remain)
    );

    // Testbench tracking variables
    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus record variables
    integer stim_rst_n;
    integer stim_start;
    reg [63:0] stim_numer;
    reg [63:0] stim_denom;

    // Expected record variables
    integer exp_busy;
    integer exp_done;
    reg [63:0] exp_quotient;
    reg [63:0] exp_remain;

    initial begin
        rst_n     = 0;
        start     = 0;
        numer     = {WIDTHN{1'b0}};
        denom     = {WIDTHD{1'b0}};
        cycle_idx = 0;
        errors    = 0;

        stim_fd = $fopen("verify_v3/tb_ch09_div_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch09_div_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch09_div_stim.txt");
            $finish;
        end

        exp_fd = $fopen("verify_v3/tb_ch09_div_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch09_div_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch09_div_expected.txt");
            $finish;
        end

        $display("=== STARTING CH09 RADIX-2 DIVIDER VERIFICATION ===");

        @(negedge clk);

        while ($fscanf(stim_fd, "%d %d %d %d\n",
                       stim_rst_n, stim_start, stim_numer, stim_denom) == 4 &&
               $fscanf(exp_fd, "%d %d %d %d\n",
                       exp_busy, exp_done, exp_quotient, exp_remain) == 4) begin

            // 1. Drive inputs during clock low phase
            rst_n = (stim_rst_n != 0) ? 1'b1 : 1'b0;
            start = (stim_start != 0) ? 1'b1 : 1'b0;
            numer = stim_numer[WIDTHN-1:0];
            denom = stim_denom[WIDTHD-1:0];

            // 2. Wait for rising edge and sample registered outputs after #1
            @(posedge clk);
            #1;

            if (busy !== ((exp_busy != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: busy mismatch DUT=%b EXP=%b",
                         cycle_idx, busy, exp_busy != 0);
                errors = errors + 1;
            end

            if (done !== ((exp_done != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: done mismatch DUT=%b EXP=%b",
                         cycle_idx, done, exp_done != 0);
                errors = errors + 1;
            end

            if (done) begin
                if (quotient !== exp_quotient[WIDTHN-1:0]) begin
                    $display("[FAIL] Cycle %0d: quotient mismatch DUT=%0d EXP=%0d",
                             cycle_idx, quotient, exp_quotient);
                    errors = errors + 1;
                end

                if (remain !== exp_remain[WIDTHD-1:0]) begin
                    $display("[FAIL] Cycle %0d: remain mismatch DUT=%0d EXP=%0d",
                             cycle_idx, remain, exp_remain);
                    errors = errors + 1;
                end
            end

            cycle_idx = cycle_idx + 1;
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        if (cycle_idx != EXPECTED_CYCLES) begin
            $display("[FAIL] Read %0d cycles, expected %0d", cycle_idx, EXPECTED_CYCLES);
            errors = errors + 1;
        end

        $display("=== Total comparison errors: %0d ===", errors);
        if (errors == 0) begin
            $display("=== ALL %0d VECTORS MATCHED SUCCESSFULLY ===", cycle_idx);
        end else begin
            $display("=== [FAIL] VERIFICATION FAILED WITH %0d ERRORS ===", errors);
        end

        $finish;
    end

endmodule
